            [r"$dx$", r"differensialdagi argument orttirmasi; «cheksiz kichik» — $\Delta x \to 0$ limitining shartli nomi", "formulalarda"],
            [r"$dy = f'(x)\,dx$", "differensial: orttirmaning chiziqli qismi, urinma bo‘ylab ko‘tarilish", "yaqinlashishlarda"],
